<template>
  <section class="flex flex-col gap-6">
    <ContractsListHeader>
      <ContractsListFilters :params="params" />
    </ContractsListHeader>
    <Card>
      <AppLoader v-if="isLoading" subject="contracts" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load contracts list" variant="table" />
      <ResponsiveTable v-else-if="data && data.items.length > 0" rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead
            v-for="value in tableHead"
            :key="value"
            class="text-accent-foreground font-normal capitalize"
          >
            {{ value }}
          </ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableRow
            v-for="contract in data.items"
            :key="contract.id"
            :to="{ name: 'contracts-id', params: { id: contract.id } }"
          >
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Canvasser">
              <div class="text-base flex flex-col">
                <span class="line-clamp-1">{{ contract.canvasser.first_name }} {{ contract.canvasser.last_name }}</span>
                <span class="text-sm text-muted-foreground line-clamp-1 break-all">{{ contract.canvasser_email }}</span>
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Project">
              <p class="text-base line-clamp-2">{{ contract.project?.name ?? '—' }}</p>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Type">
              <Badge :variant="getContractTypeLabel(contract.type).variant">
                {{ getContractTypeLabel(contract.type).name }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Status">
              <Badge
                :variant="
                  getContractStatusLabel(
                    contract.status,
                    contract.type,
                    contract.signed_by_admin,
                    contract.signed_by_canvasser
                  ).variant
                "
              >
                {{
                  getContractStatusLabel(
                    contract.status,
                    contract.type,
                    contract.signed_by_admin,
                    contract.signed_by_canvasser
                  ).name
                }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Signed">
              <div class="flex flex-col gap-1 text-sm">
                <div v-if="contract.type === 'assignment'" class="flex items-center gap-1">
                  <CheckIcon v-if="contract.signed_by_admin" class="h-4 w-4 text-green-600" />
                  <XIcon v-else class="h-4 w-4 text-muted-foreground" />
                  <span>Admin</span>
                </div>
                <div class="flex items-center gap-1">
                  <CheckIcon v-if="contract.signed_by_canvasser" class="h-4 w-4 text-green-600" />
                  <XIcon v-else class="h-4 w-4 text-muted-foreground" />
                  <span>Canvasser</span>
                </div>
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Created">
              <p class="text-base">
                {{ formatDateTzToFormat(contract.created_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
              </p>
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter :colspan="6" :cols="4" :cols-sm="4">
          <AppPagination
            :page="params.page || 1"
            :size="params.size || 10"
            :total="data.total_count"
            label="contracts"
          />
        </ResponsiveTableFooter>
      </ResponsiveTable>
      <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
      <AppEmpty v-else subject="contracts" variant="table" />
    </Card>
  </section>
</template>

<script setup lang="ts">
import { CheckIcon, XIcon } from 'lucide-vue-next';
import {
  getContractListV2,
  type ContractStatus,
  type ContractSortBy,
  type ContractType,
  type GetContractListV2Data,
  type GetContractListV2Response,
  type SortType,
} from '~/client';
import { getContractStatusLabel } from '~/constants/contracts/contractStatusConfig';
import { getContractTypeLabel } from '~/constants/contracts/contractTypeConfig';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { contractsGuidedEmpty } from '~/constants/guidedEmpty/contracts';

const { timezone } = useUserRole();

definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'contracts',
});

useHead({
  title: 'Contracts',
});

const route = useRoute('contracts');

const tableHead = ['canvasser', 'project', 'type', 'status', 'signed', 'created'];

const params = computed((): NonNullable<GetContractListV2Data['query']> => {
  const queryParams = {
    ...parsePagination(route.query),
    sort_type: (route.query.sort_type as SortType) || 'desc',
    sort_by: (route.query.sort_by as ContractSortBy) || 'created_at',
    search_query: (route.query.search_query as string) || undefined,
    statuses: processArrayQueryParameterFromUrl<ContractStatus>(route.query.statuses),
    types: processArrayQueryParameterFromUrl<ContractType>(route.query.types),
    project_ids: processArrayQueryParameterFromUrl<string>(route.query.project_ids),
    canvasser_ids: processArrayQueryParameterFromUrl<string>(route.query.canvasser_ids),
    signed_by_admin: parseBooleanQuery(route.query.signed_by_admin as string),
    signed_by_canvasser: parseBooleanQuery(route.query.signed_by_canvasser as string),
    created_date_from: (route.query.created_date_from as string) || undefined,
    created_date_to: (route.query.created_date_to as string) || undefined,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  };

  return Object.fromEntries(Object.entries(queryParams).filter(([_, value]) => value !== undefined)) as NonNullable<
    GetContractListV2Data['query']
  >;
});

const { data, error, isLoading } = useQuery({
  key: () => ['contracts-list', params.value],
  query: (): Promise<GetContractListV2Response> =>
    getContractListV2({ composable: '$fetch', query: ref(params.value) }),
  enabled: () => route.name === 'contracts',
});

const isEmpty = computed(() => !data.value || data.value.items.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(contractsGuidedEmpty, isEmpty);
</script>
