<template>
  <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 gap-4">
    <AppSearchInputQuery
      v-if="isAdminOrManager"
      :query="params.search_query || null"
      property-name="search_query"
      placeholder="Search by canvasser name or email..."
    />
    <AppComboboxQuery
      :value="`${params.sort_by || 'created_at'}|${params.sort_type || 'desc'}`"
      :items="contractsSortBy"
      property-name="sort_by|sort_type"
      :null-is-all="false"
      placeholder="Sorting"
      empty-text="No sorting options"
      :clearable="false"
      :icon="ArrowUpDownIcon"
    />
    <AppMultiComboboxQuery
      :value="params.statuses || null"
      :items="contractStatusItems"
      property-name="statuses"
      null-is-all
      items-plural-name="statuses"
      placeholder="All statuses"
      empty-text="No statuses"
      :icon="FilterIcon"
    />
    <AppMultiComboboxQuery
      :value="params.types || null"
      :items="contractTypeItems"
      property-name="types"
      null-is-all
      items-plural-name="types"
      placeholder="All types"
      empty-text="No types"
      :icon="FileTextIcon"
    />
    <FilterByProject
      v-if="isAdminOrManager"
      :value="params.project_ids || null"
      property-name="project_ids"
      :statuses="['active', 'completed']"
      :null-is-all="true"
      placeholder="All projects"
      input-placeholder="Search project..."
      empty-text="No projects found"
      items-plural-name="projects"
      :icon="BriefcaseIcon"
    />
    <FilterByUser
      v-if="isAdminOrManager"
      :value="params.canvasser_ids || null"
      property-name="canvasser_ids"
      :roles="['canvasser']"
      :statuses="['active']"
      :null-is-all="true"
      placeholder="All canvassers"
      input-placeholder="Search canvasser..."
      empty-text="No canvassers found"
      items-plural-name="canvassers"
      :icon="UserIcon"
    />
    <AppRangeDatePickerQuery
      :value="dateRange"
      :property-names="{ start: 'created_date_from', end: 'created_date_to' }"
      placeholder="Created date range"
    />
    <AppTriStateCheckboxQuery
      v-for="item in booleanFilters"
      :key="item.id"
      :value="item.value"
      :property-name="item.id"
      :label="item.label"
    />
  </div>
</template>

<script setup lang="ts">
import { ArrowUpDownIcon, BriefcaseIcon, FileTextIcon, FilterIcon, UserIcon } from 'lucide-vue-next';
import FilterByProject from '~/components/common/filters/FilterByProject.vue';
import FilterByUser from '~/components/common/filters/FilterByUser.vue';
import { contractsSortBy } from '~/constants/contracts/contractsSortBy';
import { contractStatusItems } from '~/constants/contracts/contractStatusConfig';
import { contractTypeItems } from '~/constants/contracts/contractTypeConfig';
import type { GetContractListV2Data } from '~/client';

const { isAdminOrManager } = useUserRole();

const props = defineProps<{
  params: NonNullable<GetContractListV2Data['query']>;
}>();

const dateRange = computed(() => ({
  start: (props.params.created_date_from as string | undefined) ?? null,
  end: (props.params.created_date_to as string | undefined) ?? null,
}));

const booleanFilters = computed(() => {
  const items: { id: 'signed_by_admin' | 'signed_by_canvasser'; label: string; value: boolean | null | undefined }[] = [
    { id: 'signed_by_canvasser', label: 'Signed by canvasser', value: props.params.signed_by_canvasser },
  ];
  if (isAdminOrManager.value) {
    items.unshift({ id: 'signed_by_admin', label: 'Signed by admin', value: props.params.signed_by_admin });
  }
  return items;
});
</script>
